import { parse } from '@babel/parser';
import traverse from '@babel/traverse';
import generate from '@babel/generator';

const ast = parse(src, { sourceType: 'module', plugins: ['typescript'] });

traverse(ast, {
  CallExpression(path) {
    const c = path.node.callee;
    if (c.type === 'MemberExpression' && c.property.name === 'getUser') {
      c.property.name = 'fetchUser';                 // 구조를 고친다
      path.node.arguments.reverse();                 // 인자 순서까지
    }
  },
});

fs.writeFileSync(file, generate(ast, { retainLines: true }).code);
